INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(30001, 'Song of Songs 4:1', 'Song of Songs', 4, 1, 'اے محبوبې، تۀ څومره ښائسته ينه. تۀ څومره نازنينه ينه. د نقاب نه شاته ستا سترګې ګوګوشتکې دينه. ستا زلفى وَل وَل لکه د چېلو د رمو په شان دينه، چې د جِلعاد د غرۀ نه لاندې راکوزيږينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30002, 'Song of Songs 4:2', 'Song of Songs', 4, 2, 'ستا غاښونه د سپينو ګډو په شان دينه، چې تازه ترې نه وړۍ اخوا شوې وينه، او تازه لمبولے شوے وينه. هر يو غاښ دې د بل سره جوړه دېنه، يو هم کنډم شوے نۀ دېنه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30003, 'Song of Songs 4:3', 'Song of Songs', 4, 3, 'شونډې دې تکې سرې دينه، خولۀ دې ډېره ښُکلې ښکارينه. ستا اننګى د نقاب شاته لکه د ګلابى انار ځليږينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30004, 'Song of Songs 4:4', 'Song of Songs', 4, 4, 'ستا غړۍ دومره ښائسته ده لکه د داؤد د ښار مناره، چې د زرګونو بهادرانو په ډالونو باندې شوې وى سينګاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30005, 'Song of Songs 4:5', 'Song of Songs', 4, 5, 'ستا سينې لکه د هوسو د جوړه بچو په شان دينه، چې د لاله په ګلونو کښې څريږينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30006, 'Song of Songs 4:6', 'Song of Songs', 4, 6, 'د دې نه وړاندې چې د سحر باد ولګيږينه او د شپې تيارۀ چې په ختمېدو شينه، زۀ به د مُر غر ته ورمنډه کړمه او د لوبانو غونډو ته به لاړه شمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30007, 'Song of Songs 4:7', 'Song of Songs', 4, 7, 'زما محبوبې، ستا ښائست کامِل دېنه، په تا کښې هيڅ عېب نشته دېنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30008, 'Song of Songs 4:8', 'Song of Songs', 4, 8, 'زما ناوې، د لبنان نه ما سره راشه، د لبنان نه ما سره راشه. د امانه د غرۀ د څوکو نه راکوزه شه، د حرمون او د سنير د څوکو نه ما سره راکوزه شه، د زمرو د غارونو او د پړانګانو د غونډو نه راکوزه شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30009, 'Song of Songs 4:9', 'Song of Songs', 4, 9, 'اے زما دُنيا، اے زما ناوې، زما نه دې زړۀ وړے دېنه، د سترګو په يوه اِشاره دې ما نه زړګے وړے دېنه، او د اميل يو غمى دې ما نه زړګے وړے دېنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30010, 'Song of Songs 4:10', 'Song of Songs', 4, 10, 'زما دُنيا، زما ناوې زۀ ستا په مينه کښې څومره خوشحاله يمه، د ميو نه څومره خوشحالونکى ده ستا مينه، او ستا خوشبو د هرې مصالحې نه څومره ښۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30011, 'Song of Songs 4:11', 'Song of Songs', 4, 11, 'زما ناوې، ستا د شونډو نه د شاتو د ګبين په شان خوږوالے راڅاڅيږينه، ستا د ژبې لاندې شات او پئ پراتۀ دينه، ستا د جامو نه لکه د لبنان د دِيار په شان خوشبو راځينه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30012, 'Song of Songs 4:12', 'Song of Songs', 4, 12, 'اے زما محبوبې، تۀ زما بنده باغيچه ينه، تۀ زما دُنيا ينه، او زما ناوې ينه، زما پټ باغ، زما پټه چينه ينه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30013, 'Song of Songs 4:13', 'Song of Songs', 4, 13, 'تۀ لکه د انارو باغيچه ينه، د مزېدارو مېوو نه ډکه ينه، او خوشبو دې لکه د مشکو او عنبرو په شان ده نه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30014, 'Song of Songs 4:14', 'Song of Songs', 4, 14, 'چرته چې د مشکو، زعفرانو، دارچينو او هر قسمه مصالحو بوټى پېدا کيږينه، او عُود، مُر او لوبانو خوشبوداره عطر پېدا کيږينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30015, 'Song of Songs 4:15', 'Song of Songs', 4, 15, 'تۀ د باغ چينه ينه، تۀ د تازه اوبو کوهے ينه چې د لبنان د غرونو نه رابهيږينه. محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30016, 'Song of Songs 4:16', 'Song of Songs', 4, 16, 'اے د شمال باده، راوالوځه، اے د جنوب باده راشه، زما په باغ باندې راوالوځه او د هغۀ خوشبو هرې خوا ته خوره کړه. زما جانانه خپل باغ ته راشه، او د هغې ښُکلې مېوې وخوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30017, 'Ruth 2:15', 'Ruth', 2, 15, 'وروسته د هغې چې روت د وږو د راټولولو دپاره لاړه، بوعز خپلو سړیو ته وویل: «هغه پرېږدئ چې د ګېډیو څخه هم وږي واخلي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30018, 'Ruth 2:16', 'Ruth', 2, 16, 'د ګېډیو څخه هم یو څه وږي راوباسئ او ورته یې پرېږدئ او د هغې سره سختې خبرې مه کوئ!»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30019, 'Proverbs 26:18', 'Proverbs', 26, 18, 'لکه څنګه چې یو لېونی د اور سکروټې او وژونکي غشي وروي', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30020, 'Proverbs 26:19', 'Proverbs', 26, 19, 'د هغه چا په شان دی څوک چې بل غولوي او بیا وایي چې ما ټوکې کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30021, 'Leviticus 8:20', 'Leviticus', 8, 20, 'هغه پسه ټوټې ټوټې کړ او هغه یې د سر او پاتې ټوټو او وازګې سره وسوځول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30022, 'Leviticus 8:21', 'Leviticus', 8, 21, 'څنګه چې څښتن موسی ته امر کړی ؤ، هغه د نس دنننۍ برخې او پښې ووینځلې او ټول پسه یې د قربانۍ په ځای باندې وسوځاوه. دا یوه سوځېدونکې نذرانه وه چې بوی یې په څښتن باندې ښه ولګېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30023, 'Leviticus 23:9', 'Leviticus', 23, 9, 'څښتن موسی ته وویل:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30024, 'Leviticus 23:10', 'Leviticus', 23, 10, '«د اسراییلیانو سره خبرې وکړه او ورته ووایه: کله چې تاسو هغې خاورې ته چې زه یې تاسو ته درکوم ورننوځئ او فصل یې ورېبئ، نو کاهن ته لومړنۍ ګېډۍ ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30025, 'Leviticus 23:23', 'Leviticus', 23, 23, 'څښتن موسی ته وویل:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30026, 'Leviticus 23:24', 'Leviticus', 23, 24, '«د اسراییلو قوم ته ووایه چې د هر کال د اوومې میاشتې لومړۍ ورځ د ارام کولو ځانګړې ورځ ده او د اسراییلو ټول خلک دې د سرني د اواز په اورېدلو سره د عبادت دپاره سره راټول شي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30027, 'Leviticus 23:33', 'Leviticus', 23, 33, 'څښتن موسی ته وویل:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30028, 'Leviticus 23:34', 'Leviticus', 23, 34, '«اسراییلیانو ته ووایه چې د اوومې میاشتې په پنځلسمه ورځ څښتن ته د درناوۍ دپاره د جونګړو اختر پیل کیږي. هغه اووه ورځې دوام کوي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30029, 'Leviticus 14:34', 'Leviticus', 14, 34, '«کله چې تاسو د کنعان خاورې ته چې تاسو ته یې ستاسو د ملکیت په توګه درکوم، ورننوځئ او که چېرې په تاسو کې څوک په یو کور کې یوه چڼاسکه چې ما درلېږلې ده پیدا کړي،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30030, 'Leviticus 14:35', 'Leviticus', 14, 35, 'نو د هغه کور خاوند باید لاړ شي او کاهن ته دې داسې ووایي چې ما په خپل کور کې یو شی لیدلی دی چې د چڼاسکې په شان ښکاري.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30031, '2 Samuel 24:11', '2 Samuel', 24, 11, 'په راتلونکي سهار، مخکې له دې چې داود له خوبه راپاڅي څښتن جاد ته چې د داود نبي ؤ، وویل:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30032, '2 Samuel 24:12', '2 Samuel', 24, 12, '«لاړ شه او داود ته ووایه چې څښتن داسې وایي: زه تاته د درېو سزاګانو د ټاکلو اختیار درکوم، له هغو څخه یوه وټاکه چې په تا باندې یې عملي کړم.»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30033, '1 Chronicles 2:26', '1 Chronicles', 2, 26, 'د یرحمییل دوهمه ښځه عطاره نومېدله او هغې اونام وزېږاوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30034, '1 Chronicles 2:27', '1 Chronicles', 2, 27, 'رام درې زامن درلودل: معص، یامین او عاقر.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30035, 'Song of Songs 1:1', 'Song of Songs', 1, 1, 'د حضرت سليمان خواږۀ سرودونه. محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30036, 'Song of Songs 1:2', 'Song of Songs', 1, 2, 'بيا بيا مې په خپلو شونډو سره ښُکل کړه، ځکه چې ستا مينه د ميو نه زياته مزه کړينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30037, 'Song of Songs 1:3', 'Song of Songs', 1, 3, 'ستا د عطرو خوشبوئى څومره ښُکلې ده، ستا نوم لکه د هغې د خوشبو په شان ده. نو ځکه ټولې پېغلې په تا مئينې دينه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30038, 'Song of Songs 1:4', 'Song of Songs', 1, 4, 'زر شه، ما د خپل ځان سره بوځه، تۀ زما بادشاه شه، ما خپلې کوټې ته بوځه. ښځې اے بادشاه مونږ څومره ستا دپاره خوشحاله يونه، د ميو نه زيات مونږ ستا د مينې صِفت کوونه. محبوبه دا رښتيا دى چې پېغلې په تا مئينې دينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30039, 'Song of Songs 1:5', 'Song of Songs', 1, 5, 'زۀ خو توره يمه خو ښُکلې يمه، اے د يروشلم جينکو، د قيدار د خېمو په شان توره يمه او د سليمان د خېمې د پردو په شان توره يمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30040, 'Song of Songs 1:6', 'Song of Songs', 1, 6, 'ما ته مۀ ګورئ ځکه چې زۀ غنم رنګه يمه، زما څرمنه نمر توره کړې ده. زما وروڼه ما سره وران وونه او په زبردستۍ سره هغوئ په ما د خپلو انګورو خيال ساتلو. نو بيا ما خپل خيال ونۀ ساتلو، او نۀ مې د خپل انګور خيال وکړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30041, 'Song of Songs 1:7', 'Song of Songs', 1, 7, 'ما ته ووايه، زما جانانه، تۀ به نن خپله رمه څرولو له چرته بوځې؟ او تۀ خپلې ګډې په غرمه کښې د دمې دپاره چرته راغونډوې؟ نو بيا زۀ ولې برقعه په سر سرګردانه شمه او ستا د ملګرو په رمو کښې درپسې وګرځمه محبوب', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30042, 'Song of Songs 1:8', 'Song of Songs', 1, 8, 'اے په ټولو پېغلو کښې ښائسته محبوبې، کۀ چرې تا ته دا پته نۀ وينه، نو د رمو د پښو ښاپونو پسې شه روانه، او خپل چېلى دې د شپانو د خېمو په خوا کښې وڅرونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30043, 'Song of Songs 1:9', 'Song of Songs', 1, 9, 'زما محبوبې، تۀ په ما دومره ګرانه ينه، لکه د فِرعون د شاهى آسپې په شان ښائسته ينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30044, 'Song of Songs 1:10', 'Song of Songs', 1, 10, 'ستا اننګى څومره ښائسته دينه، او هغه ستا د غوږونو والو سره ځليږينه. او ستا غړۍ څومره ښائسته ده، او د سرو سره څومره ښُکلې ښکارينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30045, 'Song of Songs 1:11', 'Song of Songs', 1, 11, 'خو مونږ به د سرو زرو والۍ درته او د سپينو زرو مرۍ جوړې کړونه. محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30046, 'Song of Songs 1:12', 'Song of Songs', 1, 12, 'کله چې زما شهزاده خپل کټ کښې آرام کولونه، نو زما د عطرو په خوشبويۍ کښې نشه نشه شونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30047, 'Song of Songs 1:13', 'Song of Songs', 1, 13, 'زما جانان د مُر زونډے دېنه، زما په سينه پروت دېنه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30048, 'Song of Songs 1:14', 'Song of Songs', 1, 14, 'زما جانان د عين‌جدى د انګورو په باغونو کښې د نکريزو د ګل په شان دېنه محبوب', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30049, 'Song of Songs 1:15', 'Song of Songs', 1, 15, 'زما محبوبې، تۀ څومره ښائسته ينه. تۀ څومره حسينه ينه، سترګې دې د ګوګوشتکو په شان ښُکلې دينه. محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30050, 'Song of Songs 1:16', 'Song of Songs', 1, 16, 'تۀ ډېر ښُکلے يې زما جانانه، تۀ څومره زړۀ وړونکے ينه، شنه ګياه به زمونږ بستره وينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30051, 'Song of Songs 1:17', 'Song of Songs', 1, 17, 'د دِيار لرګى به زمونږ د کور وى تيرونه، او د خوشبوداره دِيار لرګى زمونږ د کور دى تيرونه، او د دِيار ونه به زمونږ د کوټې چت وينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30052, '1 Samuel 6:14', '1 Samuel', 6, 14, 'ګاډۍ د یو سړي پټي ته چې یوشع نومېده او په بیت شمس کې اوسېده، راغله او هلته د یو لوی ګټ په خوا کې ودرېدله. خلکو د ګاډۍ لرګي مات کړل او غواګانې یې د سوځېدونکې نذرانې په توګه څښتن ته قرباني کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30053, '1 Samuel 6:15', '1 Samuel', 6, 15, 'لاویانو د څښتن د لوظ صندوق او هغه صندوقچه چې په هغې کې د سرو زرو شیان وو، راښکته کړل او په هغه لوی ګټ باندې یې کېښودل. په هغه ورځ د بیت شمس خلکو سوځېدونکې نذرانې او نورې قربانۍ څښتن ته وړاندې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30054, 'Genesis 31:17', 'Genesis', 31, 17, 'نو یعقوب خپل اولادونه او خپلې ښځې په اوښانو باندې سپرې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30055, 'Genesis 31:18', 'Genesis', 31, 18, 'هغه خپل ټول حیوانات مخکې کړل او هغه څه چې په بین‌النهرین کې یې ګټلي وو ټول واخیستل، ترڅو خپل پلار اسحاق ته چې په کنعان کې ؤ، لاړ شي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30056, 'Numbers 3:40', 'Numbers', 3, 40, 'څښتن موسی ته وویل: «د اسراییلو ټول مشران زامن چې عمر یې یوه میاشت یا زیات وي وشمېره او د هغوی د نومونو یو لست تیار کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30057, 'Numbers 3:41', 'Numbers', 3, 41, 'د اسراییلو د ټولو مشرانو زامنو په ځای زما دپاره لاویان واخله او د هغوی د ټولو لومړنیو زېږېدلو حیواناتو په ځای زما دپاره د لاویانو حیوانات واخله. زه څښتن یم.»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30058, 'Numbers 3:49', 'Numbers', 3, 49, 'موسی د ۲۷۳ اضافي مشرانو زامنو څخه سپین زر راټول کړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30059, 'Numbers 3:50', 'Numbers', 3, 50, 'چې د هغو وزن د سپېڅلي ځای د معیار له مخې ۱۳۶۵ سکې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30060, '1 Chronicles 25:9', '1 Chronicles', 25, 9, 'دا ۲۸۸ ساز غږوونکي او سندرغاړي د کورنیو له مخې په څلورویشت دولس کسیزو ډلو باندې ووېشل شول او هرې ډلې یو مشر درلود چې د هماغې ډلې مسوول ؤ. څنګه چې د هغوی پچې وختلې، نو د هغوی دندې په دې ډول څرګندې شوې: لومړنۍ پچه د اساف د کورنۍ څخه د یوسف په نامه، دوهمه د جدلیا او د هغه د دولسو زامنو او ورونو په نامه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
