(30082, '1 Chronicles 25:31', '1 Chronicles', 25, 31, 'او څلورویشتمه پچه د روممتي عزر او د هغه د دولسو زامنو او ورونو په نامه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30083, '1 Chronicles 12:23', '1 Chronicles', 12, 23, 'کله چې داود په حبرون کې ؤ، ډېرو په وسلو سمبال شویو کسانو د هغه له لښکرو سره لاسونه یو کړل، ترڅو هغه د شاوول په ځای پاچا کړي، لکه څنګه چې څښتن وعده کړې وه. د هغوی شمېر په لاندې ډول ؤ:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30084, '1 Chronicles 12:24', '1 Chronicles', 12, 24, 'د یهودا د قبیلې څخه: ۶۸۰۰ تنه ښه سمبال شوي کسان چې سپرونه او نېزې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
