(30086, '1 Chronicles 12:26', '1 Chronicles', 12, 26, 'د لاوي د قبیلې څخه: ۴۶۰۰ تنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30087, '1 Chronicles 12:27', '1 Chronicles', 12, 27, 'یهویاداع د هارون د کورنۍ مشر د ۳۷۰۰ تنو سره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30088, '1 Chronicles 12:28', '1 Chronicles', 12, 28, 'صادوق، یو زړور ځوان او د هغه د پلار د کورنۍ افسران: ۲۲ تنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30089, '1 Chronicles 12:29', '1 Chronicles', 12, 29, 'د بنیامین د قبیلې څخه (د شاوول خپله قبیله): ۳۰۰۰ تنه، د دغو څخه اکثره تر هغه وخته پورې د شاوول سره وفادار پاتې شوي وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30090, '1 Chronicles 12:30', '1 Chronicles', 12, 30, 'د افرایم د قبیلې څخه: ۲۰۸۰۰ تنه زړور جنګیالي چې په خپلو طایفو کې نومیالي وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30091, '1 Chronicles 12:31', '1 Chronicles', 12, 31, 'د لوېدیځې منسي د قبیلې څخه: ۱۸۰۰۰ تنه د دې دپاره غوره شوي وو چې لاړ شي او داود پاچا کړي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30092, '1 Chronicles 12:32', '1 Chronicles', 12, 32, 'د یساکار د قبیلې څخه: ۲۰۰ مشران د خپلو وطندارانو سره یو ځای چې د هغوی د امر لاندې وو. دا مشران پوهېدل چې اسراییل څه وکړي او په کوم وخت کې یې وکړي،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30093, '1 Chronicles 12:33', '1 Chronicles', 12, 33, 'د زبولون د قبیلې څخه: ۵۰۰۰۰ تنه وفادار او د اعتبار وړ کسان چې د جګړې دپاره تیار وو او د هر ډول وسلې په کارولو پوهېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30094, '1 Chronicles 12:34', '1 Chronicles', 12, 34, 'د نفتالي د قبیلې څخه: ۱۰۰۰ تنه قوماندانان د ۳۷۰۰۰ کسانو سره یوځای چې سپرونه او نېزې ورسره وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30095, '1 Chronicles 12:35', '1 Chronicles', 12, 35, 'د دان د قبیلې څخه: ۲۸۶۰۰ تنه چې د جګړې دپاره تیار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30096, '1 Chronicles 12:36', '1 Chronicles', 12, 36, 'د اشیر د قبیلې څخه: ۴۰۰۰۰ تنه تجربه لرونکي عسکر چې د جګړې دپاره تیار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30097, '1 Chronicles 12:37', '1 Chronicles', 12, 37, 'د روبین، جاد او د ختیځې منسي د قبیلو څخه (هغه قبیلې چې د اردن د سیند په ختیځ کې وې): ۱۲۰۰۰۰ تنه، چې په هر ډول وسلو سمبال شوي وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30098, 'Exodus 24:16', 'Exodus', 24, 16, 'او د څښتن جلال د سینا په غره باندې خپور شو. غر شپږ ورځې په ورېځ کې پټ ؤ او په اوومه ورځ څښتن له ورېځ څخه موسی ته غږ وکړ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30099, 'Exodus 24:17', 'Exodus', 24, 17, 'د څښتن جلال اسراییلیانو ته داسې ښکاره کېده لکه د غره په سر باندې چې اور بل وي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30100, 'Numbers 31:22', 'Numbers', 31, 22, 'سره زر، سپین زر، برنج، اوسپنه، قلعي او سرپ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');